import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.math.BigInteger;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String input = reader.readLine().trim();
        BigInteger x = new BigInteger(input);
        BigInteger mod = BigInteger.valueOf(360);
        BigInteger rotation = x.remainder(mod);
        if (rotation.compareTo(BigInteger.ZERO) < 0) {
            rotation = rotation.add(mod);
        }
        BigInteger minDeviation = mod;
        int bestK = 0;
        for (int k = 0; k < 4; k++) {
            BigInteger totalRotation = rotation.add(BigInteger.valueOf(90L * k)).remainder(mod);
            if (totalRotation.compareTo(BigInteger.ZERO) < 0) {
                totalRotation = totalRotation.add(mod);
            }
            BigInteger deviation = totalRotation;
            if (deviation.compareTo(mod.divide(BigInteger.valueOf(2))) > 0) {
                deviation = mod.subtract(deviation);
            }
            if (deviation.compareTo(minDeviation) < 0 || 
                (deviation.compareTo(minDeviation) == 0 && k < bestK)) {
                minDeviation = deviation;
                bestK = k;
            }
        }
        System.out.println(bestK);
    }
}
